&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Ability to lift a minimum of 25lbs unassisted.&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;PREFERRED QUALIFICATIONS&lt;/div&gt;
&lt;ul class=&quot;p-rich_text_list p-rich_text_list__bullet p-rich_text_list--nested&quot; data-stringify-type=&quot;unordered-list&quot; data-list-tree=&quot;true&quot; data-indent=&quot;0&quot; data-border=&quot;0&quot;&gt;
